function openModal(o){document.getElementById(o+"Modal").style.display="block"}function closeModal(o){document.getElementById(o+"Modal").style.display="none"}function showConfirmModal(){document.getElementById("confirmModal").style.display="block"}function closeConfirmModal(){document.getElementById("confirmModal").style.display="none"}function forceCloseApply(){closeConfirmModal(),closeModal("apply")}window.onclick=function(o){const e=document.getElementById("instructionsModal"),t=document.getElementById("confirmModal");o.target===e&&closeModal("instructions"),o.target===t&&closeConfirmModal()},window.addEventListener("keydown",function(o){if("Escape"===o.key){const e=document.getElementById("applyModal"),t=document.getElementById("confirmModal"),l=document.getElementById("instructionsModal");"block"===t.style.display||"block"===e.style.display?o.preventDefault():"block"===l.style.display&&closeModal("instructions")}}),document.addEventListener("click",function(o){var e=o.target.closest("[data-modal-open]");if(e)openModal(e.getAttribute("data-modal-open"));else{var t=o.target.closest("[data-modal-close]");if(t)closeModal(t.getAttribute("data-modal-close"));else{var l=o.target.closest("[data-modal-action]");if(l){var n=l.getAttribute("data-modal-action");"show-confirm"===n?showConfirmModal():"close-confirm"===n?closeConfirmModal():"force-close-apply"===n&&forceCloseApply()}}}});